import React, { useEffect, useRef, useState } from "react";
import { Button, Spinner } from "react-bootstrap";
import Select from "react-select";

import eth from "../Assets/images/ethereum.png";
import usdt from "../Assets/images/usdt.png";
import btc from "../Assets/images/btc.png";
import sol from "../Assets/images/solana.png";
import ltc from "../Assets/images/litecoin.png";
import car from "../Assets/images/cardano.png";
import { toast, ToastContainer } from "react-toastify";
import "react-toastify/dist/ReactToastify.css";
import { makeApiRequest } from "../axiosService/ApiCall";
import config from "../axiosService/Config";
import DataTable from "react-data-table-component";
import { FaCalendarAlt, FaRegCopy } from "react-icons/fa";
import { LazyLoadImage } from "react-lazy-load-image-component";
import { DateRange } from "react-date-range";
import { enUS } from "date-fns/locale";
import { MdRefresh } from "react-icons/md";
import { set } from "date-fns";
import { decryptData } from "../Auth/SecurityCrypto";
import { OverlayTrigger, Tooltip } from "react-bootstrap";
import { InfoCircle } from "react-bootstrap-icons";
import axios from "axios";

const cryptoData = [
  { img: eth, textOne: "ETH", textTwo: "Ethereum" },
  { img: usdt, textOne: "USDT", textTwo: "Tether USDT" },
  { img: btc, textOne: "BTC", textTwo: "Bitcoin" },
  { img: sol, textOne: "SOL", textTwo: "Solana" },
  { img: ltc, textOne: "LTC", textTwo: "Litecoin" },
  { img: car, textOne: "ADA", textTwo: "Cardano" },
];

const cryptoDatas = [
  { img: eth, textOne: "ETH", textTwo: "Ethereum" },
  { img: usdt, textOne: "USDT", textTwo: "Tether USDT" },
  { img: btc, textOne: "BTC", textTwo: "Bitcoin" },
  { img: sol, textOne: "SOL", textTwo: "Solana" },
  { img: ltc, textOne: "LTC", textTwo: "Litecoin" },
  { img: car, textOne: "ADA", textTwo: "Cardano" },
];

function AdminTransfer() {
  const [historyLoading, setHistoryLoading] = useState(true);
  const [isLoading, setIsLoading] = useState(false);
  const [selectedSymbol, setSelectedSymbol] = useState("");
  const [selectCurrency, setSelectCurrency] = useState("");
  const [adminData, setAdminData] = useState([]);
  const [userData, setUserData] = useState({});
  const [activeTab, setActiveTab] = useState("move");
  const [fromDate, setFromDate] = useState("");
  const [toDate, setToDate] = useState("");
  const [search, setSearch] = useState("");
  const [currentPage, setCurrentPage] = useState(1);
  const [totalPages, setTotalPages] = useState(0); // Fix
  const [loading, setLoading] = useState(false);
  const [limit, setLimit] = useState(10);
  const [showCalendar, setShowCalendar] = useState(false);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [is_Refreshing, setIs_Refreshing] = useState(false);
  const [resetPaginationToggle, setResetPaginationToggle] = useState(false);
  const [viewData, setViewData] = useState(0);
  const [editData, setEditData] = useState(null);
  // .......admintype state..........
  const [admintype, setAdmintype] = useState("");
  const [adminloading, setadminLoading] = useState(true); // loading state added


  const [range, setRange] = useState([
    {
      startDate: new Date(),
      endDate: new Date(),
      key: "selection",
    },
  ]);
  //

  const calendarRef = useRef(null);
  // useddef handleChange
  useEffect(() => {
    vieweditres();
  }, []);

  const handleChange = (selectedOption) => {
    setSelectedSymbol(selectedOption ? selectedOption.value : "");
  };
  const handleChangeCurrency = (selectedOption) => {
    handleReset();
    setSelectCurrency(selectedOption ? selectedOption.value : "");
  };

  const formatWithoutRounding = (value, decimals) => {
    const factor = Math.pow(10, decimals);
    return Math.floor(value * factor) / factor;
  };

  // const userMap = {};
  // userData.forEach((item) => {
  //   userMap[item.symbol] = formatWithoutRounding(item.remainingAmount, 6);
  // });

  const assets = [
    {
      name: "ETH",
      imgSrc: eth,
      // amount: userMap["ETH"] ?? 0,
      amount: userData?.ETH || 0,
    },
    {
      name: "USDT",
      imgSrc: usdt,
      amount: userData?.USDT || 0,
      // amount: userMap["USDT"] ?? 0,
    },
    {
      name: "BTC",
      imgSrc: btc,
      amount: userData?.BTC || 0,
      // amount: userMap["BTC"] ?? 0,
    },
    {
      name: "SOL",
      imgSrc: sol,
      amount: userData?.SOL || 0,
      // amount: userMap["SOL"] ?? 0,
    },
    {
      name: "Litecoin",
      imgSrc: ltc,
      amount: userData?.LTC || 0,
      // amount: userMap["LTC"] ?? 0,
    },
    {
      name: "Cardano",
      imgSrc: car,
      amount: userData?.ADA || 0,
      // amount: userMap["ADA"] ?? 0,
    },
  ];

  const cryptoOptions = cryptoData.map((data) => ({
    value: data.textOne,
    label: (
      <div style={{ display: "flex", alignItems: "center" }}>
        <img
          src={data.img}
          alt={data.textOne}
          style={{ width: 20, height: 20, marginRight: 10 }}
        />
        {/* {activeTab == "move"
          ? `${data.textOne} - ${data.textTwo}`
          : `${data.textOne}`} */}
        {activeTab == "move" ? `${data.textOne}` : `${data.textOne}`}
      </div>
    ),
  }));

  const cryptoOptionsdata = cryptoDatas.map((datas) => ({
    value: datas.textOne,
    label: (
      <div style={{ display: "flex", alignItems: "center" }}>
        <img
          src={datas.img}
          alt={datas.textOne}
          style={{ width: 20, height: 20, marginRight: 10 }}
        />
        {/* {datas.textOne} */}
        {/* original code */}
        {/* {activeTab == "history"
          ? `${datas.textOne} - ${datas.textTwo}`
          : `${datas.textOne}`}  */}
        {/* modified code */}
        {activeTab == "history" ? `${datas.textOne}` : `${datas.textOne}`}
      </div>
    ),
  }));

  // const userAssetData = async () => {
  //   try {
  //     let params = {
  //       url: "getuser-assets",
  //       method: "GET",
  //     };
  //     const response = await makeApiRequest(params);
  //     if (response.status) {
  //       setUserData(response.data);
  //     } else {
  //       setUserData([]);
  //     }
  //   } catch (error) {
  //     toast("Something Went Wrong...");
  //   }
  // };

  const userAssetData = async () => {
    try {
      let params = {
        url: "user-depositCount",
        method: "GET",
      };
      const response = await makeApiRequest(params);
      if (response.status) {
        setUserData(response.counts);
      } else {
        setUserData({});
      }
    } catch (error) {
      //toast("Something Went Wrong...");
    }
  };
  //
  useEffect(() => {
    userAssetData();
  }, []);

  useEffect(() => {
    if (activeTab == "history") {
      adminHistory(currentPage);
    }
  }, [
    activeTab,
    selectedSymbol,
    selectCurrency,
    search,
    fromDate,
    toDate,
    currentPage,
  ]);
  // pagination useeffect function...............
  useEffect(() => {
    adminHistory(currentPage);
  }, [currentPage, limit, search, selectCurrency, fromDate, toDate]);

  const adminHistory = async (page = 1) => {
    try {
      let queryParams = new URLSearchParams({
        search: search || "",
        type: selectCurrency || "",
        fromDate: fromDate || "",
        toDate: toDate || "",
        page: page,
        limit: limit,
      }).toString();
      let params = {
        url: `admin-moveHistory?${queryParams}`,
        method: "GET",
      };
      const response = await makeApiRequest(params);
      // console.log("response----", response);
      if (response.status) {
        setAdminData(response.data);
        setHistoryLoading(false);
        // pagination total count
        const total = response.pagination?.totalRecords || 0;
        // console.log("total", total);
        setTotalPages(total);
      } else {
        setAdminData([]);
        setHistoryLoading(false);
        setTotalPages(0);
      }
    } catch (error) {
      toast("Something Went Wrong...");
      setHistoryLoading(false);
    }
  };

  useEffect(() => {
    const handleClickOutside = (event) => {
      if (calendarRef.current && !calendarRef.current.contains(event.target)) {
        setShowCalendar(false);
      }
    };

    document.addEventListener("mousedown", handleClickOutside);

    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
    };
  }, []);

  const handleClearFilters = async () => {
    setIsRefreshing(true); // Start spinning
    setSearch("");
    setFromDate("");
    setSelectCurrency("");
    setToDate("");
    setIs_Refreshing(is_Refreshing ? false : true);

    setRange([
      {
        startDate: new Date(),
        endDate: new Date(),
        key: "selection",
      },
    ]);
    setCurrentPage(1);
    setLimit(10);

    const start = Date.now();
    // refresh previous data get line
    const prevdata = await adminHistory(1);
    // console.log("prevdata", prevdata);
    const elapsed = Date.now() - start;
    if (elapsed < 500) {
      // ensure at least 500ms rotation
      await new Promise((resolve) => setTimeout(resolve, 500 - elapsed));
    }

    setIsRefreshing(false); // Stop spinning
  };

  const handleSubmit = async () => {
    if (!selectedSymbol) {
      toast.warn("Please select a Network");
      return;
    }
    try {
      setIsLoading(true);
      const address = await axios.get("https://api.ipify.org/?format=json");

      const lastloginIpAddress = address.data.ip;

      let params = {
        url: "admin_move",
        method: "POST",
        data: { symbol: selectedSymbol, ip: lastloginIpAddress },
      };
      const AdminTransferencryptedRes = await makeApiRequest(params);
      // console.log("adminMove>>>", AdminTransferencryptedRes); 
      const AdminTransferdecryptedRes = decryptData(AdminTransferencryptedRes.data);
      // console.log("AdminTransferdecryptedRes", AdminTransferdecryptedRes);


      if (AdminTransferdecryptedRes.status === true) {
        toast.success(AdminTransferdecryptedRes.message);
      } else if (AdminTransferdecryptedRes.status === false) {
        // toast.warn(resp.message || `No ${selectedSymbol === "USDT" ? "Token" : "Coin"} in the User Wallet..`);
        toast.warn(AdminTransferdecryptedRes.message);
      } else {
        toast.error("Unexpected response from server");
      }
    } catch (error) {
      console.log("err", error);
      toast.error("Something Went Wrong...");
    } finally {
      setIsLoading(false);
      userAssetData();
      adminHistory();
    }
  };

  const handleCopy = (text) => {
    navigator.clipboard.writeText(text);
    toast.success("Address copied to clipboard!");
  };

  //   const handleSearchChange = (e) => {
  //     setSearchQuery(e.target.value);
  //     setCurrentPage(1);
  //   };

  const dateFormat = (date) => {
    try {
      const orgDate = new Date(date).toUTCString();
      // console.log('orgDate', orgDate)
      const hours = new Date(date).getUTCHours();
      const amOrPm = hours >= 12 ? "PM" : "AM";
      const formattedDate = orgDate.split(",")[1].split("GMT")[0] + amOrPm;
      return formattedDate;
    } catch (e) {
      return "Invalid Date Format";
    }
  };

  const compressString = (str) => {
    if (!str) {
      return "";
    }
    return str.length > 10 ? `${str.slice(0, 6)}...${str.slice(-4)}` : str;
  };

  const columnsone = [
    {
      name: "S.No",
      selector: (row, index) => (currentPage - 1) * limit + index + 1,
      sortable: true,
      width: "75px",
    },
    {
      name: "Email",
      selector: (row) => row.email || "--",
      sortable: true,
      width: "300px",
    },
    {
      name: "From Address",
      selector: (row) => row.from || "--",
      sortable: true,
      cell: (row) => (
        <div className="d-flex align-items-center gap-2">
          <span className="text-truncate" style={{ maxWidth: "180px" }}>
            {compressString(row.from) || "--"}
          </span>
          {row.toaddress && (
            <FaRegCopy
              className="copy-icon"
              style={{ cursor: "pointer" }}
              onClick={() => handleCopy(row.from)}
            />
          )}
        </div>
      ),
    },
    {
      name: "To Address",
      selector: (row) => row.toaddress || "--",
      sortable: true,
      cell: (row) => (
        <div className="d-flex align-items-center gap-2">
          <span className="text-truncate" style={{ maxWidth: "180px" }}>
            {compressString(row.toaddress) || "--"}
          </span>
          {row.toaddress && (
            <FaRegCopy
              className="copy-icon"
              style={{ cursor: "pointer" }}
              onClick={() => handleCopy(row.toaddress)}
            />
          )}
        </div>
      ),
    },
    {
      name: "currency",
      selector: (row) => row.symbol || "--",
      sortable: true,
      width: "100px",
    },
    // {
    //     name: 'TX-Hash',
    //     selector: row => row.txnId || "-",
    //     sortable: true,
    // },
    {
      name: "Amount",
      selector: (row) => row.amount || "--",
      sortable: true,
      width: "100px",
    },
    {
      name: "Transaction ID",
      selector: (row) => {
        if (row.txnId) {
          let explorerUrl = "#";

          if (row.symbol === "ETH" || row.symbol === "USDT") {
            explorerUrl = `${config.ETH_url}/tx/${row.txnId}`;
          } else if (row.symbol === "BTC") {
            explorerUrl = `${config.BTC_URL}/tx/${row.txnId}`;
          } else if (row.symbol === "SOL") {
            explorerUrl = `https://solscan.io/tx/${row.txnId}?cluster=${config.SOL_URL}`;
          } else if (row.symbol === "ADA") {
            explorerUrl = `${config.ADA_URL}${row.txnId}`;
          } else if(row.symbol === "LTC") {
            explorerUrl = `${config.LTC_URL}/${row.txnId}`;
          }

          return (
            <div className="d-flex align-items-center">
              <a
                href={explorerUrl}
                target="_blank"
                rel="noopener noreferrer"
                className="me-2 text-truncate"
              >
                {compressString(row.txnId) || "--"}
              </a>
              <FaRegCopy
                className="copy-icon"
                onClick={() => handleCopy(row.txnId)}
                style={{ cursor: "pointer" }}
              />
            </div>
          );
        }
        return "--";
      },
      sortable: true,
    },
    {
      name: "Date(UTC)",
      selector: (row) => dateFormat(row.createdDate) || "--",
      sortable: true,
      width: "200px",
    },
  ];

  const handleSearchChange = (e) => {
    setSearch(e.target.value);
    handleReset();
    // adminHistory(1);
  };

  const handleReset = async () => {
    setLimit(10);
    setCurrentPage(1);
    setResetPaginationToggle(!resetPaginationToggle);
  };

  const handleDateChange = (item) => {
    setRange([item.selection]);

    const formatDate = (date) => {
      return date.toLocaleDateString("en-CA");
    };

    setFromDate(formatDate(item.selection.startDate));
    setToDate(formatDate(item.selection.endDate));
    setCurrentPage(1);
  };

  const customStyles = {
    control: (base, state) => ({
      ...base,
      borderColor: state.isFocused ? "var(--color-1)" : "var(--color-1)",
      boxShadow: state.isFocused ? "0 0 0 1px var(--color-1)" : "none",
      borderRadius: "8px",
      fontSize: "13px",
      "&:hover": {
        borderColor: "var(--color-1)",
      },
      minWidth: "140px",
    }),
    menu: (base) => ({
      ...base,
      borderRadius: "8px",
      marginTop: 4,
    }),
    singleValue: (base) => ({
      ...base,
      color: "#000",
    }),
    option: (base, state) => ({
      ...base,
      backgroundColor: state.isSelected
        ? "var(--color-1)"
        : state.isFocused
          ? "#58f9b07c"
          : "white",
      color: state.isSelected ? "var(--theme-text-1)" : "black",
      ":active": {
        backgroundColor: "var(--color-1)",
      },
      cursor: "pointer",
      fontSize: "13px",
    }),
    menuPortal: (base) => ({
      ...base,
      zIndex: 9999,
    }),
  };
  // get view and edit resposne

  // console.log("viewdata", viewData);
  const vieweditres = async () => {
    setLoading(true);
    try {
      let params = {
        url: "view-edit-GetData",
        method: "GET",
        headers: {
          Authorization: `Bearer ${localStorage.getItem("token")}`,
        },
      };
      const vieweditres = await makeApiRequest(params);
      // console.log("vieweditres----", vieweditres);
      if (vieweditres.status) {
        const response = vieweditres.data;
        // console.log("response--", response);
        setEditData(response?.adminPermissions?.adminTransfer?.Edit);
        setAdmintype(response?.admin_type);
      }
    } catch (error) {
      console.log("err--", error);
      setLoading(false);

    } finally {
      setLoading(false);
    }
  };
  if (loading || admintype === "") {
    return (
      <div className="d-flex justify-content-center align-items-center vh-100">
        <Spinner animation="border" />
      </div>
    );
  }

  return admintype == "SuperAdmin" ? (

    <div className="App text-dark">
      <ToastContainer />
      <div className="container-fluid">
        <div className="row">
          <div className="col-lg-12">
            <div className="custom-nav-userlist-1">
              <ul className="nav nav-pills mb-3" id="pills-tab" role="tablist">
                <li className="nav-item" role="presentation">
                  <button
                    className={`nav-link ${activeTab === "move" ? "active" : ""
                      }`}
                    id="pills-home-tab"
                    data-bs-toggle="pill"
                    data-bs-target="#pills-home"
                    type="button"
                    role="tab"
                    aria-controls="pills-home"
                    aria-selected={activeTab === "move"}
                    onClick={() => setActiveTab("move")}
                  >
                    Admin Move
                  </button>
                </li>
                <li className="nav-item" role="presentation">
                  <button
                    className={`nav-link ${activeTab === "history" ? "active" : ""
                      }`}
                    id="pills-profile-tab"
                    data-bs-toggle="pill"
                    data-bs-target="#pills-profile"
                    type="button"
                    role="tab"
                    aria-controls="pills-profile"
                    aria-selected={activeTab === "history"}
                    onClick={() => setActiveTab("history")}
                  >
                    Admin History
                  </button>
                </li>
              </ul>
            </div>
          </div>
        </div>
        <div>
          {activeTab == "move" && (
            <>
              <h3 style={{ display: "inline-flex", alignItems: "center", gap: "6px" }}>Admin Move <OverlayTrigger
                placement="right"
                overlay={
                  <Tooltip id="admin-move-tooltip">
                    The minimum required amount may vary depending on the blockchain and the selected token or coin.
                  </Tooltip>
                }
              >
                <InfoCircle
                  size={18}
                  style={{ cursor: "pointer", marginTop: "2px" }}
                />
              </OverlayTrigger></h3> <br />
              <div className="d-flex flex-wrap">
                <Select
                  options={cryptoOptions}
                  value={cryptoOptions.find(
                    (option) => option.value === selectedSymbol
                  )} // Set default value
                  onChange={handleChange}
                  id="border-css"
                  isClearable
                  styles={customStyles}
                  isSearchable={false}
                  components={{
                    IndicatorSeparator: () => null,
                  }}
                />
                <br />
                <div className="text-center ms-4">
                  {isLoading ? (
                    <Button
                      className="custom-nav-button-1 active"
                      style={{ padding: "1px 10px" }}
                    >
                      <Spinner animation="border" />
                    </Button>
                  ) : (
                    <Button
                      type="submit"
                      className="register-btn-spinner-1 custom-nav-button-1 active"
                      onClick={handleSubmit}
                    >
                      Submit
                    </Button>
                  )}
                </div>
              </div>
              <div className="setting-tabs mt-4">
                <div className="card-body">
                  <h5 className="dash-head-1 mb-4">User Assets</h5>
                  <div className="row row-cols-1 row-cols-md-2 row-cols-lg-2 row-cols-xl-3 g-4">
                    {assets.map((asset, index) => (
                      <div className="col" key={index}>
                        <div className="card dash-card-2 h-100">
                          <div className="card-body">
                            <div className="d-flex justify-content-between align-items-center w-100">
                              <div className="d-flex gap-2 align-items-center">
                                <LazyLoadImage
                                  alt={asset.name}
                                  src={asset.imgSrc}
                                  className="dash-asset-img-2"
                                  style={{ borderRadius: "50px" }}
                                />
                                <p className="mb-0 fw-italic dash-assets-txt-1">
                                  {asset.name}
                                </p>
                              </div>
                              <p className="mb-0 fw-bold text-end">
                                {"Count"} - {asset.amount}
                              </p>
                            </div>
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              </div>
            </>
          )}
          <div>
            {activeTab == "history" && (
              <>
                <h3>Admin Transfer History</h3>
                <div className="d-flex calendor-form flex-wrap">
                  <form className="d-flex gap-2 justify-content-center align-items-center">
                    <div className="mb-3">
                      <label for="exampleInputEmail1" className="form-label">
                        From Address & Transaction-ID
                      </label>
                      <input
                        type="text"
                        className="form-control search-bar"
                        id="exampleInputEmail1"
                        aria-describedby="emailHelp"
                        placeholder="fromAddress, tx-ID...."
                        value={search}
                        onChange={handleSearchChange}
                      />
                    </div>
                    <div className="mb-3">
                      <label for="exampleInputPassword1" className="form-label">
                        Currency
                      </label>
                      <Select
                        options={cryptoOptionsdata}
                        value={
                          selectCurrency
                            ? cryptoOptionsdata.find(
                              (option) => option.value === selectCurrency
                            )
                            : null
                        }
                        onChange={handleChangeCurrency}
                        id="border-css"
                        isClearable
                        styles={customStyles}
                        isSearchable={false}
                        components={{
                          IndicatorSeparator: () => null,
                        }}
                      />
                    </div>
                    <div className="mb-3">
                      <label for="exampleInputPassword1" className="form-label">
                        Date
                      </label>

                      <div
                        ref={calendarRef}
                        style={{ position: "relative", width: "250px" }}
                      >
                        <div
                          // data edit data condition apply
                          // onClick={() => {setShowCalendar(!showCalendar); handleReset()}}
                          onClick={() => setShowCalendar(!showCalendar)}
                          style={{
                            display: "flex",
                            alignItems: "center",
                            justifyContent: "space-between",
                            padding: "6px",
                            border: "1px solid var(--color-1)",
                            borderRadius: "5px",
                            cursor: "pointer",
                            backgroundColor: "#fff",
                            fontSize: "14px",
                          }}
                        >
                          <span>
                            {fromDate && toDate
                              ? `${fromDate} - ${toDate}`
                              : "Select Date Range"}
                          </span>
                          <FaCalendarAlt style={{ color: "#555" }} />
                        </div>
                        {showCalendar && (
                          <div
                            style={{
                              position: "absolute",
                              top: "100%",
                              left: -80,
                              zIndex: 1000,
                              background: "#fff",
                              boxShadow: "0px 4px 6px rgba(0,0,0,0.1)",
                              borderRadius: "5px",
                            }}
                          >
                            <DateRange
                              editableDateInputs={true}
                              onChange={handleDateChange}
                              moveRangeOnFirstSelection={false}
                              ranges={range}
                              locale={enUS}
                              rangeColors={["#58f9b0"]}
                            />
                          </div>
                        )}
                      </div>
                    </div>
                    <div className="mb-0 mt-4">
                      <button
                        type="button"
                        className="form-label custom-nav-button-1 active cursor-pointer"
                        onClick={handleClearFilters}
                      >
                        <MdRefresh
                          style={{ fontSize: "24px" }}
                          className={isRefreshing ? "rotate-icon" : ""}
                        />
                      </button>
                    </div>
                  </form>
                </div>
                <div className="row">
                  <div className="col-lg-12">
                    <div className="liquidity-table-1">
                      <DataTable
                        key={is_Refreshing}
                        columns={columnsone}
                        data={adminData}
                        theme="solarized"
                        defaultSortAsc={true}
                        pagination
                        paginationServer
                        persistTableHead
                        paginationPerPage={limit}
                        paginationTotalRows={totalPages}
                        paginationRowsPerPageOptions={[10, 15]}
                        paginationResetDefaultPage={resetPaginationToggle}
                        onChangeRowsPerPage={(newRowsPerPage) => {
                          setLimit(newRowsPerPage);
                          setCurrentPage(1);
                        }}
                        onChangePage={(page) => setCurrentPage(page)}
                        progressPending={historyLoading}
                        progressComponent={
                          <div
                            className="py-4 w-100"
                            style={{ marginLeft: "45vw" }}
                          >
                            <Spinner animation="border" />
                          </div>
                        }
                      />
                    </div>
                  </div>
                </div>
              </>
            )}
          </div>
        </div>
      </div>
    </div>
  ) : null;

}

export default AdminTransfer;
